    id integer DEFAULT nextval('public.profiles_id_seq'::regclass) NOT NULL,
    profile_id text NOT NULL,
    first_name text NOT NULL,
    last_name text NOT NULL,
    national_id text NOT NULL,
    nationality text DEFAULT ''::text NOT NULL,
    address text DEFAULT ''::text NOT NULL,
    job_title text DEFAULT ''::text NOT NULL,
    level text DEFAULT ''::text NOT NULL,
    phone text DEFAULT ''::text NOT NULL,
    department text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    hire_date text NOT NULL,
    gender text DEFAULT 'M'::text NOT NULL,
    id_image text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    photo_url text,
    email text DEFAULT ''::text NOT NULL,
    emergency_contact text DEFAULT ''::text NOT NULL,
    third_name text DEFAULT ''::text NOT NULL,
    fourth_name text DEFAULT ''::text NOT NULL,
    date_of_birth text DEFAULT ''::text NOT NULL,
    vacation_start_date text,
    vacation_end_date text,
    vacation_notes text DEFAULT ''::text,
    employment_type text DEFAULT 'INTERNAL'::text NOT NULL,
    company_name text,
    contract_end_date text,
    id_documents jsonb DEFAULT '[]'::jsonb,
    CONSTRAINT chk_profiles_employment_type CHECK ((employment_type = ANY (ARRAY['INTERNAL'::text, 'THIRD_PARTY'::text, 'CONTRACTOR'::text, 'GUEST'::text, 'TEMPORARY'::text]))),
    CONSTRAINT chk_profiles_gender CHECK (((gender = ANY (ARRAY['M'::text, 'F'::text, 'OTHER'::text, 'male'::text, 'female'::text, 'other'::text])) OR (gender IS NULL))),
    CONSTRAINT chk_profiles_status CHECK ((status = ANY (ARRAY['UNASSIGNED'::text, 'IN_HOUSE'::text, 'CHECKED_OUT'::text, 'VACATION'::text, 'ACTIVE'::text, 'INACTIVE'::text, 'TERMINATED'::text, 'PENDING'::text, 'LEFT'::text])))
);


ALTER TABLE test.profiles OWNER TO postgres;

