    room_type text DEFAULT 'single'::text NOT NULL,
    capacity integer DEFAULT 1 NOT NULL,
    current_occupancy integer DEFAULT 0 NOT NULL,
    status text DEFAULT 'available'::text NOT NULL,
    gender text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    view text,
    bed_type text,
    classification text,
    separator_door boolean DEFAULT false,
    size text,
    size_sqm integer,
    features text,
    features_list jsonb DEFAULT '[]'::jsonb,
    notes text DEFAULT ''::text,
    is_active boolean DEFAULT true,
    updated_at timestamp with time zone DEFAULT now(),
    CONSTRAINT chk_rooms_capacity CHECK ((capacity >= 1)),
    CONSTRAINT chk_rooms_occupancy CHECK ((current_occupancy >= 0)),
    CONSTRAINT chk_rooms_status CHECK ((status = ANY (ARRAY['available'::text, 'occupied'::text, 'dirty'::text, 'occupied_dirty'::text, 'occupied_vacation'::text, 'out_of_service'::text, 'out_of_order'::text])))
);


